import{D as e}from"./index-BbvXgB4H.js";var t=`docs/references/hsk/sources/hsk3.pdf`,n=(e,n)=>`${t}#printed-pages=${e}&pdf-pages=${n}`,r=n(`163-171`,`175-183`),i=t=>({image:e(`/assets/group3/lesson-hsk3-l18-${t}-v1.webp`),imageSrcSet:`${e(`/assets/group3/lesson-hsk3-l18-${t}-720w-v1.webp`)} 720w, ${e(`/assets/group3/lesson-hsk3-l18-${t}-v1.webp`)} 1400w`}),a=(e,t)=>({...t,reading:t.pinyin,sourceRef:e}),o=(e,t,n)=>({zh:e,th:t,focus:n}),s=[[1,`怎样`,`zěnyàng`,`pron.`,`how; in what way`,`อย่างไร`,164,176],[2,`过节`,`guòjié`,`v.`,`celebrate a festival`,`ฉลองเทศกาล`,164,176],[3,`节`,`jié`,`n.`,`festival`,`เทศกาล`,164,176],[4,`节日`,`jiérì`,`n.`,`festival; holiday`,`วันเทศกาล`,164,176],[5,`联欢`,`liánhuān`,`v.`,`have a get-together`,`ร่วมสังสรรค์`,164,176],[6,`大概`,`dàgài`,`adv./adj.`,`probably; rough`,`ประมาณ / โดยคร่าว`,164,176],[7,`阿姨`,`āyí`,`n.`,`aunt`,`คุณป้า`,166,178],[8,`叔叔`,`shūshu`,`n.`,`uncle`,`คุณลุง`,166,178],[9,`收`,`shōu`,`v.`,`accept; receive`,`รับ`,166,178],[10,`总`,`zǒng`,`adv.`,`always`,`เสมอ`,166,178],[11,`起`,`qǐ`,`v.`,`raise; mention`,`ยกขึ้น / กล่าวถึง`,166,178],[12,`见面`,`jiànmiàn`,`v.`,`meet`,`พบกัน`,166,178],[13,`矿泉水`,`kuàngquánshuǐ`,`n.`,`mineral water`,`น้ำแร่`,166,178],[14,`刚刚`,`gānggāng`,`adv.`,`just now`,`เมื่อสักครู่`,166,178],[15,`出发`,`chūfā`,`v.`,`depart`,`ออกเดินทาง`,168,180],[16,`不久`,`bùjiǔ`,`adj.`,`soon; not long`,`ไม่นาน`,168,180],[17,`发生`,`fāshēng`,`v.`,`happen`,`เกิดขึ้น`,168,180],[18,`刚`,`gāng`,`adv.`,`just; a short time ago`,`เพิ่ง`,168,180],[19,`只要`,`zhǐyào`,`conj.`,`as long as`,`เพียงแค่ / ตราบใดที่`,168,180],[20,`学期`,`xuéqī`,`n.`,`semester`,`ภาคการศึกษา`,168,180],[21,`毕业`,`bìyè`,`v.`,`graduate`,`สำเร็จการศึกษา`,168,180],[22,`出生`,`chūshēng`,`v.`,`be born`,`เกิด`,170,182],[23,`过去`,`guòqù`,`n.`,`past`,`อดีต`,170,182],[24,`懂得`,`dǒngde`,`v.`,`understand; know`,`เข้าใจ`,170,182],[25,`坚持`,`jiānchí`,`v.`,`persevere in`,`ยืนหยัด / ทำต่อเนื่อง`,170,182],[26,`完成`,`wánchéng`,`v.`,`complete; finish`,`ทำให้สำเร็จ`,170,182],[27,`目标`,`mùbiāo`,`n.`,`goal`,`เป้าหมาย`,170,182],[28,`发展`,`fāzhǎn`,`v.`,`develop`,`พัฒนา`,170,182]].map(([e,t,r,i,a,o,s,c])=>({index:e,hanzi:t,pinyin:r,type:i,en:a,th:o,thAid:o,page:s,translationKind:`editorial-aid`,sourceRef:n(String(s),String(c))})),c=n(`164`,`176`),l=n(`165-166`,`177-178`),u=n(`167-168`,`179-180`),d={bai:{hanzi:`白家月`,pinyin:`Bái Jiāyuè`,nameTh:`ไป๋เจียเยว่`,nameEn:`Bai Jiayue`,...i(`spring-festival-flight`),imageFocus:`30% center`},liWen:{hanzi:`李文`,pinyin:`Lǐ Wén`,nameTh:`หลี่เหวิน`,nameEn:`Li Wen`,...i(`spring-festival-flight`),imageFocus:`70% center`},liUncle:{hanzi:`李叔叔`,pinyin:`Lǐ shūshu`,nameTh:`คุณลุงหลี่`,nameEn:`Uncle Li`,...i(`new-year-visit`),imageFocus:`30% center`},zhangAunt:{hanzi:`张阿姨`,pinyin:`Zhāng āyí`,nameTh:`คุณป้าจาง`,nameEn:`Aunt Zhang`,...i(`family-photos`),imageFocus:`70% center`}},f=[{id:`h3l18-spring-festival-flight`,number:`01`,glyph:`春`,title:`第一次在中国过年`,titleTh:`ฉลองตรุษจีนที่จีนครั้งแรก`,titleEn:`First Spring Festival in China`,place:`飞机上`,placeTh:`บนเครื่องบิน`,...i(`spring-festival-flight`),source:`Text 1 · หน้าเล่ม 164 · PDF หน้า 176`,sourcePage:`164`,sourceRef:c,imageAlt:{zh:`春节饺子和年货`,th:`เกี๊ยวและของฉลองตรุษจีน`,en:`Dumplings and Spring Festival decorations`},context:`在飞机上，白家月和李文在聊天儿。`,contextTh:`บนเครื่องบิน ไป๋เจียเยว่กับหลี่เหวินคุยกัน`,contextEn:`On the plane, Bai Jiayue and Li Wen were chatting.`,characters:[{role:`A`,profile:`bai`,noteZh:`第一次在中国过年的人`,noteTh:`ผู้ฉลองตรุษจีนที่จีนครั้งแรก`,noteEn:`The first-time Spring Festival guest`},{role:`B`,profile:`liWen`,noteZh:`邀请朋友回家的人`,noteTh:`ผู้เชิญเพื่อนกลับบ้าน`,noteEn:`The friend inviting her home`}],lines:[a(c,{role:`A`,speaker:`白家月`,hanzi:`我要在中国过年，真开心。`,pinyin:`Wǒ yào zài Zhōngguó guònián, zhēn kāixīn.`,en:`I am going to celebrate New Year in China. I am so happy.`,th:`ฉันจะฉลองปีใหม่ที่จีน ดีใจจริง ๆ`,visual:o(`在中国过年`,`ฉลองปีใหม่ที่จีน`,`30% center`)}),a(c,{role:`B`,speaker:`李文`,hanzi:`第一次请外国朋友来家里过春节，我也很高兴。`,pinyin:`Dì-yī cì qǐng wàiguó péngyou lái jiā li guò Chūnjié, wǒ yě hěn gāoxìng.`,en:`It is my first time inviting a foreign friend home for Spring Festival, and I am happy too.`,th:`นี่เป็นครั้งแรกที่ฉันชวนเพื่อนต่างชาติมาฉลองตรุษจีนที่บ้าน ฉันก็ดีใจ`,visual:o(`请外国朋友过春节`,`ชวนเพื่อนต่างชาติฉลองตรุษจีน`,`70% center`)}),a(c,{role:`A`,speaker:`白家月`,hanzi:`你们怎样过节？`,pinyin:`Nǐmen zěnyàng guòjié?`,en:`How do you celebrate the festival?`,th:`พวกเธอฉลองเทศกาลอย่างไร?`,visual:o(`怎样过节`,`ฉลองอย่างไร`,`32% center`)}),a(c,{role:`B`,speaker:`李文`,hanzi:`春节是中国最重要的节日，我们一般会回家，跟家人一起过。`,pinyin:`Chūnjié shì Zhōngguó zuì zhòngyào de jiérì, wǒmen yìbān huì huí jiā, gēn jiārén yìqǐ guò.`,en:`Spring Festival is China's most important festival. We usually go home and celebrate with family.`,th:`ตรุษจีนเป็นเทศกาลสำคัญที่สุดของจีน ปกติเรากลับบ้านฉลองกับครอบครัว`,visual:o(`跟家人一起过`,`ฉลองกับครอบครัว`,`68% center`)}),a(c,{role:`A`,speaker:`白家月`,hanzi:`那你跟家人会一起做什么？`,pinyin:`Nà nǐ gēn jiārén huì yìqǐ zuò shénme?`,en:`What do you and your family do together?`,th:`แล้วเธอกับครอบครัวทำอะไรด้วยกัน?`,visual:o(`一起做什么`,`ทำอะไรด้วยกัน`,`34% center`)}),a(c,{role:`B`,speaker:`李文`,hanzi:`我们家会一边包饺子，一边看春节联欢晚会，一直到十二点以后才睡觉。`,pinyin:`Wǒmen jiā huì yìbiān bāo jiǎozi, yìbiān kàn Chūnjié Liánhuān Wǎnhuì, yìzhí dào shí'èr diǎn yǐhòu cái shuìjiào.`,en:`My family makes dumplings while watching the Spring Festival Gala, and we do not sleep until after midnight.`,th:`ครอบครัวฉันห่อเกี๊ยวไปดูงานกาลาตรุษจีนไป และนอนหลังเที่ยงคืน`,visual:o(`一边包饺子一边看晚会`,`ห่อเกี๊ยวไปดูงานกาลาไป`,`66% center`)}),a(c,{role:`A`,speaker:`白家月`,hanzi:`听起来很有意思。春节放几天假？`,pinyin:`Tīng qǐlai hěn yǒuyìsi. Chūnjié fàng jǐ tiān jià?`,en:`That sounds interesting. How many days off are there?`,th:`ฟังดูน่าสนใจ ตรุษจีนหยุดกี่วัน?`,visual:o(`春节放几天假`,`ตรุษจีนหยุดกี่วัน`,`36% center`)}),a(c,{role:`B`,speaker:`李文`,hanzi:`大概七八天。`,pinyin:`Dàgài qī bā tiān.`,en:`About seven or eight days.`,th:`ประมาณเจ็ดแปดวัน`,visual:o(`大概七八天`,`ประมาณเจ็ดแปดวัน`,`64% center`)})],qte:{after:3,prompt:{zh:`李文家过春节时会做什么？`,th:`ครอบครัวหลี่เหวินทำอะไรตอนตรุษจีน?`,en:`What does Li Wen's family do during Spring Festival?`},options:[{value:`包饺子看联欢晚会`,zh:`包饺子，看联欢晚会`,pinyin:`bāo jiǎozi, kàn liánhuān wǎnhuì`,th:`ห่อเกี๊ยวและดูงานกาลา`},{value:`去国外旅游`,zh:`去国外旅游`,pinyin:`qù guówài lǚyóu`,th:`เที่ยวต่างประเทศ`},{value:`很早睡觉`,zh:`很早睡觉`,pinyin:`hěn zǎo shuìjiào`,th:`นอนเร็วมาก`}],correct:`包饺子看联欢晚会`,evidence:`李文：一边包饺子，一边看春节联欢晚会。`,evidenceTh:`หลี่เหวิน: ห่อเกี๊ยวไปดูงานกาลาตรุษจีนไป`,sourceRef:c},builder:{prompt:{zh:`重组概数句`,th:`เรียงประโยคจำนวนโดยประมาณ`,en:`Rebuild the approximate-number sentence`},answer:[`春节`,`大概放`,`七八天`,`假`],tiles:[`假`,`七八天`,`春节`,`大概放`],gloss:{春节:`ตรุษจีน`,大概放:`หยุดประมาณ`,七八天:`เจ็ดแปดวัน`,假:`วันหยุด`},translationTh:`ตรุษจีนหยุดประมาณเจ็ดแปดวัน`,translationEn:`Spring Festival has about seven or eight days off.`,evidence:`Text 1 · หน้าเล่ม 164`,sourceRef:c}},{id:`h3l18-new-year-visit`,number:`02`,glyph:`饺`,title:`一起包饺子`,titleTh:`ห่อเกี๊ยวด้วยกัน`,titleEn:`Making dumplings together`,place:`李文家`,placeTh:`บ้านหลี่เหวิน`,...i(`new-year-visit`),source:`Text 2 · หน้าเล่ม 165–166 · PDF หน้า 177–178`,sourcePage:`165-166`,sourceRef:l,imageAlt:{zh:`春节家庭拜年场景`,th:`ไป๋เจียเยว่ไปอวยพรปีใหม่ที่บ้านหลี่เหวิน`,en:`A Spring Festival visit at Li Wen's home`},context:`在李文家，白家月给李文的父母拜年。`,contextTh:`ที่บ้านหลี่เหวิน ไป๋เจียเยว่อวยพรปีใหม่ให้พ่อแม่ของหลี่เหวิน`,contextEn:`At Li Wen's home, Bai Jiayue wished his parents a happy New Year.`,characters:[{role:`A`,profile:`bai`,noteZh:`来拜年的客人`,noteTh:`แขกที่มาอวยพรปีใหม่`,noteEn:`The New Year guest`},{role:`B`,profile:`liUncle`,noteZh:`欢迎客人的李叔叔`,noteTh:`คุณลุงหลี่ผู้ต้อนรับแขก`,noteEn:`Uncle Li welcoming the guest`},{role:`C`,profile:`zhangAunt`,noteZh:`正在包饺子的张阿姨`,noteTh:`คุณป้าจางที่กำลังห่อเกี๊ยว`,noteEn:`Aunt Zhang making dumplings`}],lines:[a(l,{role:`A`,speaker:`白家月`,hanzi:`张阿姨，李叔叔。过年好！这是我准备的礼物，请收下。`,pinyin:`Zhāng āyí, Lǐ shūshu. Guònián hǎo! Zhè shì wǒ zhǔnbèi de lǐwù, qǐng shōuxià.`,en:`Aunt Zhang, Uncle Li, Happy New Year! This is a gift I prepared. Please accept it.`,th:`คุณป้าจาง คุณลุงหลี่ สวัสดีปีใหม่! นี่คือของขวัญที่ฉันเตรียมไว้ โปรดรับไว้`,visual:o(`请收下礼物`,`โปรดรับของขวัญ`,`30% center`)}),a(l,{role:`B`,speaker:`李叔叔`,hanzi:`谢谢家月，你太客气了！`,pinyin:`Xièxie Jiāyuè, nǐ tài kèqi le!`,en:`Thank you, Jiayue. You are too kind!`,th:`ขอบคุณเจียเยว่ เกรงใจเกินไปแล้ว!`,visual:o(`你太客气了`,`เกรงใจเกินไปแล้ว`,`70% center`)}),a(l,{role:`C`,speaker:`张阿姨`,hanzi:`总听小文说起你，今天终于有机会见面了。`,pinyin:`Zǒng tīng Xiǎowén shuōqǐ nǐ, jīntiān zhōngyú yǒu jīhuì jiànmiàn le.`,en:`I always hear Xiaowen mention you. Today we finally have a chance to meet.`,th:`ได้ยินเสี่ยวเหวินพูดถึงเธอเสมอ วันนี้ในที่สุดก็ได้พบกัน`,visual:o(`终于有机会见面`,`ในที่สุดก็ได้พบกัน`,`32% center`)}),a(l,{role:`A`,speaker:`白家月`,hanzi:`谢谢您和叔叔请我来家里做客。`,pinyin:`Xièxie nín hé shūshu qǐng wǒ lái jiā li zuòkè.`,en:`Thank you and Uncle for inviting me to your home.`,th:`ขอบคุณคุณป้ากับคุณลุงที่เชิญฉันมาเป็นแขกที่บ้าน`,visual:o(`请我来家里做客`,`เชิญมาเป็นแขกที่บ้าน`,`68% center`)}),a(l,{role:`B`,speaker:`李叔叔`,hanzi:`桌子上有饮料，还有矿泉水，你想喝什么就自己拿。`,pinyin:`Zhuōzi shang yǒu yǐnliào, hái yǒu kuàngquánshuǐ, nǐ xiǎng hē shénme jiù zìjǐ ná.`,en:`There are drinks and mineral water on the table. Take whatever you would like.`,th:`บนโต๊ะมีเครื่องดื่มและน้ำแร่ อยากดื่มอะไรก็หยิบเองได้`,visual:o(`想喝什么就自己拿`,`อยากดื่มอะไรก็หยิบเอง`,`34% center`)}),a(l,{role:`C`,speaker:`张阿姨`,hanzi:`你先坐着看会儿电视，饺子很快就包好了。`,pinyin:`Nǐ xiān zuòzhe kàn huìr diànshì, jiǎozi hěn kuài jiù bāo hǎo le.`,en:`Sit and watch television for a while. The dumplings will soon be ready.`,th:`นั่งดูโทรทัศน์สักครู่ เกี๊ยวจะห่อเสร็จเร็ว ๆ นี้`,visual:o(`饺子很快就包好了`,`เกี๊ยวจะห่อเสร็จเร็ว ๆ นี้`,`66% center`)}),a(l,{role:`A`,speaker:`白家月`,hanzi:`我刚刚看视频学会了包饺子，我跟你们一起包吧。`,pinyin:`Wǒ gānggāng kàn shìpín xuéhuì le bāo jiǎozi, wǒ gēn nǐmen yìqǐ bāo ba.`,en:`I just learned to make dumplings from a video. Let me make them with you.`,th:`ฉันเพิ่งดูวิดีโอแล้วห่อเกี๊ยวเป็น ให้ฉันห่อด้วยกันกับพวกคุณเถอะ`,visual:o(`刚刚学会包饺子`,`เพิ่งห่อเกี๊ยวเป็น`,`40% center`)})],qte:{after:3,prompt:{zh:`白家月刚刚学会了什么？`,th:`ไป๋เจียเยว่เพิ่งทำอะไรเป็น?`,en:`What did Bai Jiayue just learn to do?`},options:[{value:`包饺子`,zh:`包饺子`,pinyin:`bāo jiǎozi`,th:`ห่อเกี๊ยว`},{value:`做面条`,zh:`做面条`,pinyin:`zuò miàntiáo`,th:`ทำบะหมี่`},{value:`唱中文歌`,zh:`唱中文歌`,pinyin:`chàng Zhōngwén gē`,th:`ร้องเพลงจีน`}],correct:`包饺子`,evidence:`白家月：我刚刚看视频学会了包饺子。`,evidenceTh:`ไป๋เจียเยว่: ฉันเพิ่งดูวิดีโอแล้วห่อเกี๊ยวเป็น`,sourceRef:l},builder:{prompt:{zh:`重组“刚刚”句`,th:`เรียงประโยคที่ใช้ 刚刚`,en:`Rebuild the 刚刚 sentence`},answer:[`我刚刚`,`看视频`,`学会了`,`包饺子`],tiles:[`包饺子`,`学会了`,`我刚刚`,`看视频`],gloss:{我刚刚:`ฉันเพิ่ง`,看视频:`ดูวิดีโอ`,学会了:`เรียนจนทำเป็น`,包饺子:`ห่อเกี๊ยว`},translationTh:`ฉันเพิ่งดูวิดีโอแล้วเรียนห่อเกี๊ยวจนเป็น`,translationEn:`I just learned to make dumplings by watching a video.`,evidence:`Text 2 · หน้าเล่ม 166`,sourceRef:l}},{id:`h3l18-family-photos`,number:`03`,glyph:`照`,title:`李文出国前的照片`,titleTh:`รูปก่อนหลี่เหวินไปต่างประเทศ`,titleEn:`Photos before Li Wen left`,place:`李文家`,placeTh:`บ้านหลี่เหวิน`,...i(`family-photos`),source:`Text 3 · หน้าเล่ม 167–168 · PDF หน้า 179–180`,sourcePage:`167-168`,sourceRef:u,imageAlt:{zh:`家庭相册`,th:`ไป๋เจียเยว่ดูกับคุณป้าจางดูอัลบั้มครอบครัว`,en:`Bai Jiayue and Aunt Zhang viewing a family album`},context:`在李文家，李文妈妈和白家月在聊天儿。`,contextTh:`ที่บ้านหลี่เหวิน แม่ของหลี่เหวินกับไป๋เจียเยว่คุยกัน`,contextEn:`At Li Wen's home, his mother and Bai Jiayue were chatting.`,characters:[{role:`A`,profile:`bai`,noteZh:`看家庭照片的人`,noteTh:`ผู้ดูรูปครอบครัว`,noteEn:`The guest viewing family photos`},{role:`B`,profile:`zhangAunt`,noteZh:`想念儿子的妈妈`,noteTh:`แม่ที่คิดถึงลูกชาย`,noteEn:`The mother missing her son`}],lines:[a(u,{role:`A`,speaker:`白家月`,hanzi:`这张照片是李文出国前照的吗？`,pinyin:`Zhè zhāng zhàopiàn shì Lǐ Wén chūguó qián zhào de ma?`,en:`Was this photo taken before Li Wen went abroad?`,th:`รูปนี้ถ่ายก่อนหลี่เหวินไปต่างประเทศหรือ?`,visual:o(`出国前照的照片`,`รูปที่ถ่ายก่อนไปต่างประเทศ`,`30% center`)}),a(u,{role:`B`,speaker:`张阿姨`,hanzi:`对，这是他从北京出发时，我们全家在机场照的。`,pinyin:`Duì, zhè shì tā cóng Běijīng chūfā shí, wǒmen quán jiā zài jīchǎng zhào de.`,en:`Yes. Our whole family took it at the airport when he departed from Beijing.`,th:`ใช่ ครอบครัวเราถ่ายที่สนามบินตอนเขาออกเดินทางจากปักกิ่ง`,visual:o(`全家在机场照的`,`ทั้งครอบครัวถ่ายที่สนามบิน`,`70% center`)}),a(u,{role:`A`,speaker:`白家月`,hanzi:`那是三四年前吧？`,pinyin:`Nà shì sān sì nián qián ba?`,en:`That was three or four years ago, right?`,th:`นั่นเมื่อสามสี่ปีก่อนใช่ไหม?`,visual:o(`三四年前`,`สามสี่ปีก่อน`,`32% center`)}),a(u,{role:`B`,speaker:`张阿姨`,hanzi:`是啊，时间过得真快，好像是不久前发生的一样。`,pinyin:`Shì a, shíjiān guò de zhēn kuài, hǎoxiàng shì bùjiǔ qián fāshēng de yíyàng.`,en:`Yes, time passes so quickly. It seems as if it happened not long ago.`,th:`ใช่ เวลาผ่านเร็วจริง ๆ เหมือนเพิ่งเกิดขึ้นไม่นาน`,visual:o(`好像是不久前发生的`,`เหมือนเพิ่งเกิดไม่นาน`,`68% center`)}),a(u,{role:`A`,speaker:`白家月`,hanzi:`您一定特别想李文吧？`,pinyin:`Nín yídìng tèbié xiǎng Lǐ Wén ba?`,en:`You must miss Li Wen very much, right?`,th:`คุณป้าคงคิดถึงหลี่เหวินมากใช่ไหม?`,visual:o(`特别想李文`,`คิดถึงหลี่เหวินมาก`,`34% center`)}),a(u,{role:`B`,speaker:`张阿姨`,hanzi:`他刚离开家时，我很不习惯，只要几天不跟他视频，就很想他。`,pinyin:`Tā gāng líkāi jiā shí, wǒ hěn bù xíguàn, zhǐyào jǐ tiān bù gēn tā shìpín, jiù hěn xiǎng tā.`,en:`When he had just left home, I was not used to it. If I go only a few days without a video call, I miss him very much.`,th:`ตอนเขาเพิ่งออกจากบ้าน ฉันไม่ชิน เพียงไม่ได้วิดีโอคอลไม่กี่วันก็คิดถึงมาก`,visual:o(`只要几天不视频就很想他`,`ไม่ได้วิดีโอคอลไม่กี่วันก็คิดถึง`,`66% center`)}),a(u,{role:`A`,speaker:`白家月`,hanzi:`还有最后一个学期就要毕业了，他很快就会回来了。`,pinyin:`Hái yǒu zuìhòu yí ge xuéqī jiù yào bìyè le, tā hěn kuài jiù huì huílai le.`,en:`He has only one semester left before graduation. He will return soon.`,th:`เหลืออีกภาคเรียนสุดท้ายก็จะจบแล้ว เขาจะกลับมาเร็ว ๆ นี้`,visual:o(`最后一个学期就毕业`,`อีกภาคเรียนเดียวก็จบ`,`40% center`)})],qte:{after:3,prompt:{zh:`李文全家的照片在哪里照的？`,th:`รูปครอบครัวของหลี่เหวินถ่ายที่ไหน?`,en:`Where was Li Wen's family photo taken?`},options:[{value:`机场`,zh:`机场`,pinyin:`jīchǎng`,th:`สนามบิน`},{value:`学校`,zh:`学校`,pinyin:`xuéxiào`,th:`โรงเรียน`},{value:`饭馆`,zh:`饭馆`,pinyin:`fànguǎn`,th:`ร้านอาหาร`}],correct:`机场`,evidence:`张阿姨：我们全家在机场照的。`,evidenceTh:`คุณป้าจาง: ครอบครัวเราถ่ายที่สนามบิน`,sourceRef:u},builder:{prompt:{zh:`重组“只要……就……”句`,th:`เรียงประโยคเงื่อนไขเพียงพอ`,en:`Rebuild the sufficient-condition sentence`},answer:[`只要几天`,`不跟他视频`,`就`,`很想他`],tiles:[`很想他`,`就`,`不跟他视频`,`只要几天`],gloss:{只要几天:`เพียงไม่กี่วัน`,不跟他视频:`ไม่ได้วิดีโอคอลกับเขา`,就:`ก็`,很想他:`คิดถึงเขามาก`},translationTh:`เพียงไม่ได้วิดีโอคอลกับเขาไม่กี่วัน ก็คิดถึงมาก`,translationEn:`If I go only a few days without a video call, I miss him greatly.`,evidence:`Text 3 · หน้าเล่ม 168`,sourceRef:u}}],p={id:`hsk3-l18`,slug:`lesson-18`,level:`hsk3`,number:18,featured:!1,sourceRef:r,source:{title:`新HSK教程 3 · New HSK Course 3`,lesson:`Lesson 18 · 我学会了包饺子`,printedPages:`163–171`,pdfPages:`175–183`,file:`hsk3.pdf`,sourceRef:r},title:{zh:`我学会了包饺子`,pinyin:`Wǒ xuéhuì le bāo jiǎozi`,en:`I learned how to make dumplings`,thAid:`ฉันห่อเกี๊ยวเป็นแล้ว`},summary:{zh:`谈春节习俗、拜年、包饺子和留学成长经历。`,en:`Discuss Spring Festival customs, New Year visits, dumpling making, and growth through study abroad.`,thAid:`พูดคุยเรื่องประเพณีตรุษจีน การอวยพรปีใหม่ การห่อเกี๊ยว และประสบการณ์เติบโตจากการเรียนต่างประเทศ`},translationPolicy:{kind:`editorial-aid`,labelTh:`คำแปลไทยเพื่อช่วยเรียน เรียบเรียงจากต้นฉบับ`},objectives:[{zh:`能听懂并描述生活中的变化和成长经历。`,en:`Be able to understand and describe life changes and personal growth.`,thAid:`ฟังเข้าใจและบรรยายการเปลี่ยนแปลงในชีวิตและประสบการณ์การเติบโต`,sourceRef:n(`163`,`175`)},{zh:`能听懂并使用概数表达不确定的数量。`,en:`Be able to understand and use approximate numbers to express uncertain quantities.`,thAid:`ฟังเข้าใจและใช้จำนวนโดยประมาณเพื่อบอกปริมาณที่ไม่แน่นอน`,sourceRef:n(`163`,`175`)},{zh:`掌握“只要”的用法，能表达充分条件和结果。`,en:`Master 只要 to express a sufficient condition and its result.`,thAid:`ใช้ 只要 เพื่อบอกเงื่อนไขที่เพียงพอและผลลัพธ์`,sourceRef:n(`163`,`175`)},{zh:`了解中国传统节日“春节”的习俗。`,en:`Gain an understanding of the customs of the traditional Chinese festival, Spring Festival.`,thAid:`เรียนรู้ธรรมเนียมของเทศกาลจีนดั้งเดิมอย่างเทศกาลตรุษจีน`,sourceRef:n(`163`,`175`)}],contents:[{number:`00`,title:`目标与热身`,titleTh:`เป้าหมายและการเตรียมบท`,detail:`Objectives · Warm-Up`,pages:`163`,route:`/home/hsk3/lesson-18/preface/`,sourceRef:n(`163`,`175`)},{number:`01`,title:`第一次在中国过年`,titleTh:`ฉลองตรุษจีนที่จีนครั้งแรก`,detail:`Text 1 · New Words 1–6`,pages:`164–165`,scene:1,sourceRef:n(`164-165`,`176-177`)},{number:`02`,title:`一起包饺子`,titleTh:`ห่อเกี๊ยวด้วยกัน`,detail:`Text 2 · New Words 7–14`,pages:`165–166`,scene:2,sourceRef:l},{number:`03`,title:`李文出国前的照片`,titleTh:`รูปก่อนหลี่เหวินไปต่างประเทศ`,detail:`Text 3 · New Words 15–21`,pages:`167–168`,scene:3,sourceRef:u},{number:`04`,title:`成长、练习与活动`,titleTh:`การเติบโต แบบฝึก และกิจกรรม`,detail:`Text 4 · Exercises · Activity`,pages:`169–171`,sourceRef:n(`169-171`,`181-183`)}],vocabulary:s,grammarFocus:[{title:`概数表达法`,titleEn:`Approximate numbers`,explanationZh:`相邻的两个数字连用，表示不确定的数量。`,explanationEn:`Two adjacent numerals used together express an approximate quantity.`,thAid:`ใช้ตัวเลขสองจำนวนที่ติดกันเพื่อบอกปริมาณโดยประมาณ`,examples:[`春节大概放七八天假。`,`这些照片是三四年前照的。`],sourceRef:n(`165`,`177`)},{title:`“刚才”和“刚刚”`,titleEn:`Comparison of 刚才 and 刚刚`,explanationZh:`“刚才”是时间名词，可放句首或主语后；“刚刚”是时间副词，放在主语后、动词前。`,explanationEn:`刚才 is a time noun that may begin a sentence; 刚刚 is a time adverb placed after the subject and before the verb.`,thAid:`刚才 เป็นคำนามเวลา วางต้นประโยคได้ ส่วน 刚刚 เป็นคำวิเศษณ์เวลา วางหลังประธานหน้ากริยา`,examples:[`刚才的电话是我妈妈打来的。`,`我刚刚看视频学会了包饺子。`],sourceRef:n(`166-167`,`178-179`)},{title:`条件复句“只要……，就……”`,titleEn:`Sufficient condition 只要……就……`,explanationZh:`“只要”后是实现结果的充分条件，“就”后是有该条件便能产生的结果。`,explanationEn:`The clause after 只要 gives a sufficient condition, and the clause after 就 gives its result.`,thAid:`อนุประโยคหลัง 只要 เป็นเงื่อนไขที่เพียงพอ ส่วนหลัง 就 เป็นผลลัพธ์`,examples:[`只要几天不跟他视频，就很想他。`,`只要你坚持每天早睡，身体就会好起来。`],sourceRef:n(`168-169`,`180-181`)}],characters:d,scenes:f};export{p as LESSON_HSK3_L18};